M(idl, r"""
public static boolean solidAt(@WLD@ w, int x, int y, int z) {
  if (API != null) return API.solid(x, y, z);
  try {
    if (w == null || y < 0) return true;
    if (y >= 320) return false;
    @CHS@ cs = w.getChunkStore();
    @REF@ c = cs.getChunkReference(@CHU@.indexChunkFromBlock(x, z));
    if (c == null || !c.isValid()) return true;
    @REF@ r = cs.getChunkSectionReferenceAtBlock(x, y, z);
    if (r == null || !r.isValid()) return true;
    Object s = cs.getStore().getComponent(r, @BSEC@.getComponentType());
    if (!(s instanceof @BSEC@)) return true;
    Object t = @BTY@.getAssetMap().getAsset(((@BSEC@) s).get(x, y, z));
    if (!(t instanceof @BTY@)) return false;
    return ((@BTY@) t).getMaterial() == @BMAT@.Solid;
  } catch (Throwable t) { return true; }
}""")
M(idl, r"""
public static boolean clear(@WLD@ w, double[] op, double r, double h) {
  int ox = (int) Math.floor(op[0]), oy = (int) Math.floor(op[1]), oz = (int) Math.floor(op[2]);
  int top = (int) Math.ceil(h) + 1;
  for (int y = 1; y <= top; y++) if (solidAt(w, ox, oy + y, oz)) return false;
  int fy = (int) Math.floor(op[1] + h);
  for (int i = 0; i < 12; i++) {
    double a = (double) i * Math.PI / 6.0;
    int x = (int) Math.floor(op[0] + Math.cos(a) * r), z = (int) Math.floor(op[2] + Math.sin(a) * r);
    if (solidAt(w, x, fy, z) || solidAt(w, x, fy + 1, z) || solidAt(w, x, fy + 2, z)) return false;
  }
  return true;
}""")
