# the nearest creature that passes: the cheap half on all in range, the dear half on at most MAX_TRY from the near end; null = none
M(idl, r"""
public static @REF@ pick(@PKG@.PetView v, @CAC@ acc, double[] op, long now) {
  if (v == null || op == null || noAggroWorld(v.world)) return null;
  double rg = (double) aggroRange();
  java.util.List l = new java.util.ArrayList(scan(acc, op[0], op[1], op[2], rg));          // the engine's list is its per-thread one: any later spatial query (another mod's bridge call) would refill it
  int n = l.size();
  if (n == 0) return null;
  double[] ds = new double[n];
  double[][] ps = new double[n][];
  for (int i = 0; i < n; i++) {
    Object r = l.get(i);
    ds[i] = 1.0E9;
    if (!(r instanceof @REF@)) continue;
    double[] p = @PKG@.PetWorld.pos(acc, (@REF@) r);
    if (p == null) continue;
    double d = @PKG@.PetFly.dist(p[0], p[1], p[2], op[0], op[1], op[2]);
    if (d <= rg && quick(v, acc, (@REF@) r, now) == null) { ds[i] = d; ps[i] = p; }
  }
  for (int t = 0; t < MAX_TRY; t++) {
    int b = -1;
    for (int i = 0; i < n; i++) if (ds[i] < 1.0E8 && (b < 0 || ds[i] < ds[b])) b = i;
    if (b < 0) return null;
    ds[b] = 1.0E9;
    @REF@ r = (@REF@) l.get(b);
    if (dear(v, op, ps[b]) == null) { PICKS.incrementAndGet(); return r; }
    REFUSED.incrementAndGet();
  }
  return null;
}""")
